<?php
namespace App\Filament\Resources;
use App\Models\ServiceRequest;
use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class ServiceRequestResource extends Resource { protected static ?string $model=ServiceRequest::class; protected static ?string $navigationIcon='heroicon-o-inbox'; public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('service_id')->relationship('service','name_en')->required(),Forms\Components\TextInput::make('full_name')->required(),Forms\Components\TextInput::make('mobile')->required(),Forms\Components\TextInput::make('email')->email()->required(),Forms\Components\Textarea::make('details')->required(),Forms\Components\Select::make('status')->options(['new'=>'New','under_review'=>'Under Review','awaiting_documents'=>'Awaiting Documents','quotation_sent'=>'Quotation Sent','payment_pending'=>'Payment Pending','in_progress'=>'In Progress','submitted_to_authority'=>'Submitted to Authority','completed'=>'Completed','rejected'=>'Rejected','cancelled'=>'Cancelled'])->required(),Forms\Components\Textarea::make('customer_note'),Forms\Components\Textarea::make('internal_note')]);} public static function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('reference')->searchable(),Tables\Columns\TextColumn::make('full_name')->searchable(),Tables\Columns\TextColumn::make('service.name_en'),Tables\Columns\BadgeColumn::make('status'),Tables\Columns\TextColumn::make('created_at')->dateTime()])->filters([Tables\Filters\SelectFilter::make('status')->options(['new'=>'New','in_progress'=>'In Progress','awaiting_documents'=>'Awaiting Documents','completed'=>'Completed'])])->actions([Tables\Actions\EditAction::make()]);} public static function getPages():array{return ['index'=>Pages\ListServiceRequests::route('/'),'edit'=>Pages\EditServiceRequest::route('/{record}/edit')];} }
